        TELEMETRY_RAW_MAX_SECONDS
        if resolution == "raw"
        else TELEMETRY_DOWNSAMPLED_MAX_SECONDS
    )
    if (end - start).total_seconds() > limit:
        raise ServiceError("query range exceeds the limit for this resolution")
    return {
        "metric": metric,
        "start": start,
        "end": end,
        "resolution": resolution,
    }

