@staticmethod
def _rollback_rate_quota_locked(
    usage: dict[str, tuple[int, int]], device_id: str, amount: int
) -> None:
    """归还同一锁内刚占用且随后失败（如落盘 503）的额度。"""
    record = usage.get(device_id)
    if record is None:
        return
    window, used = record
    usage[device_id] = (window, max(0, used - amount))

